// One dated row per keyword from the free summary rows; the per-point rows stay in the Apify dataset.
const week = new Date().toISOString().slice(0, 10);
return $input.all()
  .map((i) => i.json)
  .filter((r) => r.type === 'keyword-summary')
  .map((r) => ({
    json: {
      week,
      business: r.businessName,
      keyword: r.keyword,
      grid: `${r.gridSize}x${r.gridSize}, ${r.gridSpacingKm} km`,
      averageRankWhereFound: r.averageRankWhereFound,
      averageRankAllPoints: r.averageRankAllPoints,
      shareOfLocalVoiceTop3Pct: r.shareOfLocalVoiceTop3Pct,
      pointsFound: `${r.pointsFound}/${r.pointsTotal}`,
      topCompetitor: r.topCompetitor ? r.topCompetitor.name : '',
    },
  }));
